from target_module import data_plan_cost

def test_case_1():
    result = data_plan_cost(0)
    assert result == {"status": "ok", "cost": 20.0}

def test_case_2():
    result = data_plan_cost(5)
    assert result == {"status": "ok", "cost": 20.0}

def test_case_3():
    result = data_plan_cost(10)
    assert result == {"status": "ok", "cost": 28.0}

def test_case_4():
    result = data_plan_cost(15)
    assert result == {"status": "ok", "cost": 35.0}

def test_case_5():
    result = data_plan_cost(20)
    assert result == {"status": "ok", "cost": 40.0}

def test_case_6():
    result = data_plan_cost(25)
    assert result == {"status": "ok", "cost": 45.0}

def test_case_7():
    result = data_plan_cost(30)
    assert result == {"status": "ok", "cost": 50.0}

def test_case_8():
    result = data_plan_cost(35)
    assert result == {"status": "ok", "cost": 50.0}

def test_case_9():
    result = data_plan_cost(40)
    assert result == {"status": "ok", "cost": 50.0}

def test_case_10():
    result = data_plan_cost(45)
    assert result == {"status": "ok", "cost": 50.0}

def test_case_11():
    result = data_plan_cost(50)
    assert result == {"status": "ok", "cost": 50.0}

def test_case_12():
    result = data_plan_cost(-1)
    assert result == {"status": "error", "cost": 0.0}

