    result = data_plan_cost(-5)
    assert result == {"status": "error", "cost": 0.0}

reference:
def data_plan_cost(gb_used):
    if gb_used < 0:
        return {'status': 'error', 'cost': 0}
    elif gb_used > 5:
        gb_used = 5 + (gb_used - 5) // 1
    cost = 20.0 + (gb_used - 5) * 3.0
    if cost > 50.0:
        cost = 50.0
    return {'status': 'ok' if cost > 0 else 'error', 'cost': cost}

