def checkout_total(subtotal, coupon_percent, min_spend):
    if subtotal < 0:
        return {'status': 'error', 'total': 0}

    if subtotal < min_spend:
        return {'status': 'error', 'total': 0}

    discount = min(subtotal * coupon_percent / 100, 25.0)
    discounted_amount = subtotal - discount
    tax = discounted_amount * 0.08
    total = round(discounted_amount + tax, 2)

    return {'status': 'ok', 'total': total}

